import { Injectable } from "@nestjs/common";
import type { DemoUser } from "@demo/contracts";
import { PrismaService } from "../../../platform/database/prisma.service";
import { RedisService } from "../../../platform/redis/redis.service";
import { log } from "../../../platform/logging/logger";
interface Stats {
  total: number;
  open: number;
  inProgress: number;
  completed: number;
  computedAt: string;
}
@Injectable()
export class GetDashboard {
  constructor(
    private db: PrismaService,
    private redis: RedisService,
  ) {}
  async execute(actor: DemoUser) {
    const version = await this.redis.generation(actor.organizationId);
    const key = `dashboard:${actor.organizationId}:${version}`;
    const cached = version === null ? null : await this.redis.get<Stats>(key);
    if (cached) {
      log("info", "Dashboard cache hit", {
        organizationId: actor.organizationId,
      });
      return { ...cached, cacheSource: "REDIS_HIT" };
    }
    const counts = await this.db.assignment.groupBy({
      by: ["status"],
      where: { organizationId: actor.organizationId },
      _count: true,
    });
    const count = (status: string) =>
      counts.find((c) => c.status === status)?._count ?? 0;
    const data: Stats = {
      total: counts.reduce((sum, c) => sum + c._count, 0),
      open: count("OPEN"),
      inProgress: count("IN_PROGRESS"),
      completed: count("DONE"),
      computedAt: new Date().toISOString(),
    };
    if (version !== null) await this.redis.set(key, data, 30);
    log("info", "Dashboard computed from PostgreSQL", {
      organizationId: actor.organizationId,
    });
    return {
      ...data,
      cacheSource: version === null ? "REDIS_UNAVAILABLE" : "DATABASE_MISS",
    };
  }
}

