import { Injectable, OnModuleDestroy } from "@nestjs/common";
import Redis from "ioredis";
import { log } from "../logging/logger";
import { randomUUID } from "node:crypto";

@Injectable()
export class RedisService implements OnModuleDestroy {
  readonly client = new Redis(
    process.env.REDIS_URL ?? "redis://127.0.0.1:56379",
    {
      maxRetriesPerRequest: 1,
      enableOfflineQueue: false,
    },
  );
  constructor() {
    this.client.on("error", () =>
      log("warn", "Redis unavailable; cache reads will use PostgreSQL"),
    );
  }
  async get<T>(key: string): Promise<T | null> {
    try {
      const value = await this.client.get(key);
      return value ? (JSON.parse(value) as T) : null;
    } catch {
      return null;
    }
  }
  async set(key: string, value: unknown, seconds = 30) {
    try {
      await this.client.set(key, JSON.stringify(value), "EX", seconds);
    } catch {
      /* Optional caching must not break reads. */
    }
  }
  async generation(organizationId: string): Promise<string | null> {
    try {
      const key = `dashboard-version:${organizationId}`;
      await this.client.set(key, randomUUID(), "NX");
      return await this.client.get(key);
    } catch {
      return null;
    }
  }
  async invalidate(organizationId: string) {
    try {
      await this.client.set(
        `dashboard-version:${organizationId}`,
        randomUUID(),
      );
    } catch {
      log("warn", "Cache invalidation failed; TTL bounds staleness", {
        organizationId,
      });
    }
  }
  onModuleDestroy() {
    this.client.disconnect();
  }
}

