import { Field, ObjectType, Resolver, Subscription } from "@nestjs/graphql";
import { UseGuards } from "@nestjs/common";
import type { DemoUser } from "@demo/contracts";
import { AuthenticationGuard } from "../../auth/guards/authentication.guard";
import { CurrentActor } from "../../auth/decorators/current-actor.decorator";
import { PubsubService } from "../../../platform/redis/pubsub.service";
@ObjectType()
class WorkspaceChanged {
  @Field() kind!: string;
  @Field() entityId!: string;
}
@Resolver()
@UseGuards(AuthenticationGuard)
export class AssignmentsSubscription {
  constructor(private events: PubsubService) {}
  @Subscription(() => WorkspaceChanged)
  workspaceChanged(@CurrentActor() actor: DemoUser) {
    const iterator = this.events.events(actor.organizationId);
    let first = true;
    let pending: ReturnType<typeof iterator.next> | undefined;
    // An explicit iterator lets cancellation release a pending subscription immediately.
    return {
      [Symbol.asyncIterator]() {
        return this;
      },
      async next() {
        if (first) {
          first = false;
          pending = iterator.next();
          return {
            done: false as const,
            value: {
              workspaceChanged: {
                organizationId: actor.organizationId,
                kind: "READY",
                entityId: "",
              },
            },
          };
        }
        const result = pending ?? iterator.next();
        pending = undefined;
        return result;
      },
      return() {
        return iterator.return!();
      },
      throw(error: unknown) {
        return iterator.throw!(error);
      },
    };
  }
}

