import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from "@nestjs/common";
import type { DemoUser } from "@demo/contracts";
import { PrismaService } from "../../../platform/database/prisma.service";
import { PubsubService } from "../../../platform/redis/pubsub.service";
import { log } from "../../../platform/logging/logger";
import { DEMO_USERS } from "../../auth/demo-users";
import { AssignmentPolicy } from "../policies/assignment.policy";
import { CreateAssignmentInput } from "../graphql/assignment.input";
@Injectable()
export class CreateAssignment {
  constructor(
    private db: PrismaService,
    private policy: AssignmentPolicy,
    private events: PubsubService,
  ) {}
  async execute(actor: DemoUser, input: CreateAssignmentInput) {
    if (!this.policy.canCreate(actor))
      throw new ForbiddenException("You cannot create assignments.");
    if (!this.policy.canManage(actor) && input.assigneeId !== actor.id)
      throw new ForbiddenException("You can only assign work to yourself.");
    if (
      !DEMO_USERS.some(
        (u) =>
          u.id === input.assigneeId &&
          u.organizationId === actor.organizationId,
      )
    )
      throw new BadRequestException(
        "Choose a teammate from your organization.",
      );
    const result = await this.db.$transaction(async (tx) => {
      const project = await tx.project.findFirst({
        where: { id: input.projectId, organizationId: actor.organizationId },
      });
      if (!project) throw new NotFoundException("Project not found.");
      const assignment = await tx.assignment.create({
        data: {
          ...input,
          title: input.title.trim(),
          organizationId: actor.organizationId,
        },
      });
      await tx.activity.create({
        data: {
          organizationId: actor.organizationId,
          actorName: actor.name,
          message: `created “${assignment.title}”`,
        },
      });
      return assignment;
    });
    log("info", "Assignment created", {
      assignmentId: result.id,
      actorId: actor.id,
    });
    await this.events.changed({
      organizationId: actor.organizationId,
      kind: "ASSIGNMENT_CREATED",
      entityId: result.id,
    });
    return result;
  }
}

import {
  ForbiddenException,
  Injectable,
  NotFoundException,
} from "@nestjs/common";
import type { DemoUser } from "@demo/contracts";
import { PrismaService } from "../../../platform/database/prisma.service";
import { PubsubService } from "../../../platform/redis/pubsub.service";
import { AssignmentPolicy } from "../policies/assignment.policy";
import { AddCommentInput } from "../graphql/assignment.input";
@Injectable()
export class AddComment {
  constructor(
    private db: PrismaService,
    private policy: AssignmentPolicy,
    private events: PubsubService,
  ) {}
  async execute(actor: DemoUser, input: AddCommentInput) {
    const result = await this.db.$transaction(async (tx) => {
      const assignment = await tx.assignment.findFirst({
        where: { id: input.assignmentId, ...this.policy.readScope(actor) },
      });
      if (!assignment) throw new NotFoundException("Assignment not found.");
      if (!this.policy.canComment(actor, assignment))
        throw new ForbiddenException("Your role is read-only.");
      const comment = await tx.comment.create({
        data: { ...input, body: input.body.trim(), authorId: actor.id },
      });
      await tx.activity.create({
        data: {
          organizationId: actor.organizationId,
          actorName: actor.name,
          message: `commented on “${assignment.title}”`,
        },
      });
      return comment;
    });
    await this.events.changed({
      organizationId: actor.organizationId,
      kind: "COMMENT_ADDED",
      entityId: input.assignmentId,
    });
    return result;
  }
}

