import { Args, Mutation, Query, Resolver } from "@nestjs/graphql";
import { UseGuards, NotFoundException } from "@nestjs/common";
import type { DemoUser } from "@demo/contracts";
import { AuthenticationGuard } from "../../auth/guards/authentication.guard";
import { CurrentActor } from "../../auth/decorators/current-actor.decorator";
import { PrismaService } from "../../../platform/database/prisma.service";
import { AssignmentType, CommentType } from "./assignment.type";
import {
  AddCommentInput,
  AssignmentFilter,
  CreateAssignmentInput,
} from "./assignment.input";
import { ListAssignments } from "../queries/list-assignments";
import { CreateAssignment } from "../use-cases/create-assignment";
import { ChangeAssignmentStatus } from "../use-cases/change-assignment-status";
import { AddComment } from "../use-cases/add-comment";
@Resolver()
@UseGuards(AuthenticationGuard)
export class AssignmentsResolver {
  constructor(
    private list: ListAssignments,
    private create: CreateAssignment,
    private change: ChangeAssignmentStatus,
    private comment: AddComment,
    private db: PrismaService,
  ) {}
  @Query(() => [AssignmentType])
  assignments(
    @CurrentActor() actor: DemoUser,
    @Args("filter", { defaultValue: {} }) filter: AssignmentFilter,
  ) {
    return this.list.execute(actor, filter);
  }
  @Query(() => [CommentType])
  async assignmentComments(
    @CurrentActor() actor: DemoUser,
    @Args("assignmentId") assignmentId: string,
  ) {
    if (
      !(await this.db.assignment.findFirst({
        where: { id: assignmentId, organizationId: actor.organizationId },
      }))
    )
      throw new NotFoundException("Assignment not found.");
    return this.db.comment.findMany({
      where: { assignmentId },
      orderBy: { createdAt: "asc" },
      take: 100,
    });
  }
  @Mutation(() => AssignmentType)
  createAssignment(
    @CurrentActor() actor: DemoUser,
    @Args("input") input: CreateAssignmentInput,
  ) {
    return this.create.execute(actor, input);
  }
  @Mutation(() => AssignmentType)
  startAssignment(@CurrentActor() actor: DemoUser, @Args("id") id: string) {
    return this.change.execute(actor, id, "IN_PROGRESS");
  }
  @Mutation(() => AssignmentType)
  completeAssignment(@CurrentActor() actor: DemoUser, @Args("id") id: string) {
    return this.change.execute(actor, id, "DONE");
  }
  @Mutation(() => CommentType)
  addComment(
    @CurrentActor() actor: DemoUser,
    @Args("input") input: AddCommentInput,
  ) {
    return this.comment.execute(actor, input);
  }
}

import { Parent, ResolveField, Resolver } from "@nestjs/graphql";
import type { DemoUser } from "@demo/contracts";
import { CurrentActor } from "../../auth/decorators/current-actor.decorator";
import { AssignmentPolicy } from "../policies/assignment.policy";
import { completionReason, startReason } from "../domain/assignment.rules";
import { AssignmentCapabilities, AssignmentType } from "./assignment.type";
@Resolver(() => AssignmentType)
export class AssignmentFieldsResolver {
  constructor(private policy: AssignmentPolicy) {}
  @ResolveField(() => AssignmentCapabilities)
  capabilities(
    @CurrentActor() actor: DemoUser,
    @Parent() assignment: AssignmentType,
  ): AssignmentCapabilities {
    const denied = this.policy.canEdit(actor, assignment)
      ? null
      : "Only the assignee or a manager can do this.";
    const completeReason = denied ?? completionReason(assignment.status);
    const start = denied ?? startReason(assignment.status);
    return {
      canComplete: !completeReason,
      completeReason,
      canStart: !start,
      startReason: start,
      canComment: this.policy.canComment(actor, assignment),
    };
  }
}

