import {
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from "@nestjs/common";
import type { DemoUser } from "@demo/contracts";
import { PrismaService } from "../../../platform/database/prisma.service";
import { PubsubService } from "../../../platform/redis/pubsub.service";
import { AssignmentPolicy } from "../policies/assignment.policy";
import { completionReason, startReason } from "../domain/assignment.rules";
import { log } from "../../../platform/logging/logger";
@Injectable()
export class ChangeAssignmentStatus {
  constructor(
    private db: PrismaService,
    private policy: AssignmentPolicy,
    private events: PubsubService,
  ) {}
  async execute(actor: DemoUser, id: string, next: "IN_PROGRESS" | "DONE") {
    const result = await this.db.$transaction(async (tx) => {
      const assignment = await tx.assignment.findFirst({
        where: { id, ...this.policy.readScope(actor) },
      });
      if (!assignment) throw new NotFoundException("Assignment not found.");
      if (!this.policy.canEdit(actor, assignment))
        throw new ForbiddenException(
          "Only its assignee or a manager can change this assignment.",
        );
      const reason =
        next === "DONE"
          ? completionReason(assignment.status)
          : startReason(assignment.status);
      if (reason) throw new ConflictException(reason);
      // Compare the state we checked, so concurrent changes cannot both succeed.
      const updated = await tx.assignment.updateMany({
        where: {
          id,
          status: assignment.status,
          updatedAt: assignment.updatedAt,
        },
        data: { status: next },
      });
      if (!updated.count)
        throw new ConflictException(
          "Assignment changed. Refresh and try again.",
        );
      await tx.activity.create({
        data: {
          organizationId: actor.organizationId,
          actorName: actor.name,
          message: `${next === "DONE" ? "completed" : "started"} “${assignment.title}”`,
        },
      });
      return tx.assignment.findUniqueOrThrow({ where: { id } });
    });
    log("info", "Assignment status changed", {
      assignmentId: id,
      status: next,
      actorId: actor.id,
    });
    await this.events.changed({
      organizationId: actor.organizationId,
      kind: "ASSIGNMENT_UPDATED",
      entityId: id,
    });
    return result;
  }
}

