import { Injectable } from "@nestjs/common";
import type { Assignment } from "@prisma/client";
import type { DemoUser } from "@demo/contracts";

@Injectable()
export class AssignmentPolicy {
  readScope(actor: DemoUser) {
    return { organizationId: actor.organizationId };
  }
  canCreate(actor: DemoUser) {
    return actor.permissions.includes("assignments.write");
  }
  canManage(actor: DemoUser) {
    return actor.permissions.includes("assignments.manage");
  }
  canEdit(
    actor: DemoUser,
    assignment: Pick<Assignment, "organizationId" | "assigneeId">,
  ) {
    return (
      actor.organizationId === assignment.organizationId &&
      this.canCreate(actor) &&
      (this.canManage(actor) || assignment.assigneeId === actor.id)
    );
  }
  canComment(actor: DemoUser, assignment: Pick<Assignment, "organizationId">) {
    return (
      actor.organizationId === assignment.organizationId &&
      this.canCreate(actor)
    );
  }
}

