import { Injectable, OnModuleInit, OnModuleDestroy } from "@nestjs/common";
import { PubSub } from "graphql-subscriptions";
import { RedisService } from "./redis.service";
import { log } from "../logging/logger";

export interface WorkspaceEvent {
  organizationId: string;
  kind: string;
  entityId: string;
}
@Injectable()
export class PubsubService implements OnModuleInit, OnModuleDestroy {
  private readonly local = new PubSub();
  private subscriber;
  constructor(private readonly redis: RedisService) {
    this.subscriber = redis.client.duplicate({ enableOfflineQueue: true });
    this.subscriber.on("error", () =>
      log("warn", "Realtime Redis subscriber disconnected"),
    );
    this.subscriber.on("message", (_channel, raw) => {
      try {
        const event = JSON.parse(raw) as WorkspaceEvent;
        void this.local.publish(`workspace:${event.organizationId}`, {
          workspaceChanged: event,
        });
      } catch {
        log("warn", "Invalid workspace notification ignored");
      }
    });
  }
  async onModuleInit() {
    await this.subscriber.subscribe("fieldwork:changes");
  }
  async changed(event: WorkspaceEvent) {
    await this.redis.invalidate(event.organizationId);
    try {
      await this.redis.client.publish(
        "fieldwork:changes",
        JSON.stringify(event),
      );
    } catch {
      log("warn", "Realtime delivery failed after commit", {
        entityId: event.entityId,
      });
    }
  }
  events(organizationId: string) {
    return this.local.asyncIterableIterator<{
      workspaceChanged: WorkspaceEvent;
    }>(`workspace:${organizationId}`);
  }
  onModuleDestroy() {
    this.subscriber.disconnect();
  }
}

