          },
        },
        controller.signal,
      )
        .then((result) => {
          setData(result);
          setError("");
        })
        .catch((err) => {
          if (!controller.signal.aborted)
            setError(
              err instanceof Error ? err.message : "Could not load workspace.",
            );
        })
        .finally(() => {
          running = false;
          if (dirty) {
            dirty = false;
            run();
          }
        });
    };
    reload.current = run;
    const timer = setTimeout(run, 100);
    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [actor, projectId, status, search]);
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    const schedule = () => {
      if (!timer)
        timer = setTimeout(() => {
          timer = undefined;
          refresh();
        }, 200);
    };
    const client = createClient({
      url: process.env.NEXT_PUBLIC_WS_URL ?? "ws://127.0.0.1:4310/graphql",
      connectionParams: { "x-demo-user": actor },
      retryAttempts: Infinity,
      on: {
        connected: () => setConnection("Connected"),
        closed: () => setConnection("Reconnecting"),
        error: () => setConnection("Reconnecting"),
      },
    });
    const unsubscribe = client.subscribe<{
      workspaceChanged: { kind: string };
    }>(
      { query: CHANGES },
      {
        next: (result) => {
          if (result.data) {
            setLastEvent(result.data.workspaceChanged.kind);
            schedule();
          }
        },
        error: () => setConnection("Unavailable"),
        complete: () => {},
      },
    );
    window.addEventListener("focus", schedule);
    return () => {
      if (timer) clearTimeout(timer);
      window.removeEventListener("focus", schedule);
      unsubscribe();
      void client.dispose();
    };
  }, [actor, refresh]);
  return { data, error, connection, refresh, lastEvent };
}

