'use client';
import { useEffect, useState } from 'react';
import { graphqlRequest, type GraphQLResult } from '../api/orders.client';
import { CANCEL_ORDER, CREATE_ORDER, DEMO_USERS, ordersQuery } from '../graphql/orders.operations';

interface Identity { id: string; name: string; role: string }
interface Order {
  id: string; title: string; customerName: string; status: string; total?: number;
  capabilities: { cancel: { authorized: boolean; available: boolean; reason: string | null } };
}
interface PageData { viewer: { name: string; role: string; canCreate: boolean }; orders: Order[] }

export function OrdersLab() {
  const [identities, setIdentities] = useState<Identity[]>([]);
  const [actor, setActor] = useState('alice');
  const [includeTotal, setIncludeTotal] = useState(false);
  const [result, setResult] = useState<GraphQLResult<PageData> | null>(null);
  const [revision, setRevision] = useState(0);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [mutation, setMutation] = useState<{ query: string; variables: unknown; response: unknown } | null>(null);
  const [title, setTitle] = useState('');
  const [identityRetry, setIdentityRetry] = useState(0);
  const query = ordersQuery(includeTotal);
  const data = result?.data;

  useEffect(() => {
    const controller = new AbortController();
    graphqlRequest<{ demoUsers: Identity[] }>(DEMO_USERS, undefined, {}, controller.signal).then(response => {
      if (response.errors) throw new Error(response.errors[0].message);
      setIdentities(response.data?.demoUsers ?? []);
    }).catch((err: Error) => { if (err.name !== 'AbortError') setError(err.message); });
    return () => controller.abort();
  }, [identityRetry]);

  useEffect(() => {
    const controller = new AbortController();
    graphqlRequest<PageData>(query, actor, {}, controller.signal).then(setResult)
      .catch((err: Error) => { if (err.name !== 'AbortError') setError(err.message); });
    return () => controller.abort();
  }, [query, actor, revision]);

  async function runMutation(document: string, variables: Record<string, unknown>, asActor = actor) {
    setBusy(true); setError('');
    try {
      const response = await graphqlRequest(document, asActor, variables);
      setMutation({ query: document, variables, response });
      if (!response.errors) {
        setTitle('');
        setResult(await graphqlRequest<PageData>(query, actor));
      }
    } catch (err) { setError(err instanceof Error ? err.message : 'Request failed'); }
    finally { setBusy(false); }
  }

  return <main>
    <header><span className="badge">A SMALL WORKING EXAMPLE</span><h1>GraphQL, one step at a time.</h1><p>Frontend chooses the fields. Backend checks the rules.</p></header>
    <section className="controls" aria-label="Query controls">
      <label>Act as<select value={actor} disabled={busy || !identities.length} onChange={event => {
        setActor(event.target.value); setResult(null); setMutation(null); setError('');
      }}>{identities.length ? identities.map(identity => <option key={identity.id} value={identity.id}>{identity.name} · {identity.role}</option>) : <option value="alice">Loading users…</option>}</select></label>
      <label className="checkbox"><input type="checkbox" checked={includeTotal} disabled={busy} onChange={event => { setIncludeTotal(event.target.checked); setResult(null); }} />Request total</label>
      <span className="endpoint">POST /graphql</span>
    </section>
    {error && <p className="error" role="alert">{error} <button onClick={() => { setError(''); setResult(null); setRevision(v => v + 1); setIdentityRetry(v => v + 1); }}>Retry</button></p>}
    {result?.errors && <p className="error" role="alert">{result.errors.map(item => item.message).join('; ')}</p>}
    <section className="card">
      <div className="section-heading"><h2>1. The UI</h2><span>{data ? `${data.viewer.name} · ${data.orders.length} orders` : 'Loading…'}</span></div>
      <div className="table-wrap"><table><thead><tr><th>Order</th><th>Owner</th><th>Status</th>{includeTotal && <th>Total</th>}<th>Cancel capability</th></tr></thead><tbody>
        {data?.orders.map(order => <tr key={order.id}><td>{order.title}</td><td>{order.customerName}</td><td><span className={`status ${order.status}`}>{order.status}</span></td>
          {includeTotal && <td>{order.total === undefined ? '—' : `$${(order.total / 100).toFixed(2)}`}</td>}
          <td>{order.capabilities.cancel.authorized ? <button disabled={busy || !order.capabilities.cancel.available} onClick={() => void runMutation(CANCEL_ORDER, { id: order.id })}>Cancel</button> : <span className="muted">No permission</span>}
          {order.capabilities.cancel.reason && <small>{order.capabilities.cancel.reason}</small>}</td></tr>)}
        {!data && <tr><td colSpan={includeTotal ? 5 : 4}>Loading authorized records…</td></tr>}
        {data?.orders.length === 0 && <tr><td colSpan={includeTotal ? 5 : 4}>No visible orders.</td></tr>}
      </tbody></table></div>
      {data?.viewer.canCreate && <form onSubmit={event => { event.preventDefault(); void runMutation(CREATE_ORDER, { input: { title, total: 4900 } }); }}><input aria-label="New order title" placeholder="New order title" required maxLength={100} value={title} onChange={event => setTitle(event.target.value)} disabled={busy} /><button disabled={busy}>Create $49 order</button></form>}
      <p className="hint">Alice can cancel her pending orders. Maya can cancel anyone’s in her organization. Leo can only read.</p>
    </section>
    <div className="code-grid">
      <section className="card"><h2>2. What the frontend asks</h2><p>Toggle “Request total” above. Only this selection changes.</p><pre>{query}</pre></section>
      <section className="card"><h2>3. What GraphQL returns</h2><p>The actual response envelope from the server.</p><pre aria-label="Query response">{JSON.stringify(result, null, 2) ?? 'Loading…'}</pre></section>
    </div>
    <section className="card"><div className="section-heading"><h2>4. Mutations still enforce access</h2><button disabled={busy} onClick={() => void runMutation(CREATE_ORDER, { input: { title: 'Forbidden probe', total: 100 } }, 'leo')}>Try create as Leo</button></div><p>This bypasses the UI restriction. The backend guard calls the policy and rejects it.</p>
      {mutation ? <div className="code-grid"><div><h3>Operation + variables</h3><pre>{mutation.query}{'\n\n'}{JSON.stringify(mutation.variables, null, 2)}</pre></div><div><h3>Actual mutation response</h3><pre aria-label="Mutation response">{JSON.stringify(mutation.response, null, 2)}</pre></div></div> : <p className="hint">Create or cancel an order, or try the forbidden request, to see a mutation here.</p>}
    </section>
    <section className="flow"><h2>Where the code lives</h2><p><code>orders.operations.ts</code> → <code>orders.resolver.ts</code> → <code>queries/</code> or <code>use-cases/</code> → <code>order.policy.ts</code></p><p>The creation guard also calls the policy. Input validation checks data shape. Domain rules prevent cancelling shipped orders.</p></section>
    <footer>Learning demo: a spoofable identity header and in-memory data. Restart the API to reset. GraphQL limits response fields; this example still loads complete records in memory.</footer>
  </main>;
}

export interface GraphQLResult<T> {
  data?: T | null;
  errors?: { message: string; extensions?: { code?: string } }[];
}

// HTTP 200 can contain GraphQL errors. Always inspect the response envelope.
export async function graphqlRequest<T>(query: string, actorId?: string, variables: Record<string, unknown> = {}, signal?: AbortSignal): Promise<GraphQLResult<T>> {
  const response = await fetch('/graphql', {
    method: 'POST', cache: 'no-store', signal,
    headers: { 'Content-Type': 'application/json', ...(actorId ? { 'x-demo-user': actorId } : {}) },
    body: JSON.stringify({ query, variables }),
  });
  const result: GraphQLResult<T> = await response.json();
  if (!response.ok && !result.errors) throw new Error(`HTTP ${response.status}`);
  return result;
}
